        d.artifacts.map(function (a) { return '<div class="card p-3 mb-2"><div class="d-flex align-items-center"><span class="badge bg-dark me-2">' + a.order + '</span><b>' + esc(a.objectTypeLabel || '') + ' ' + esc(a.objectName) + '</b><span class="small-muted ms-2">' + esc(a.package) + (a.toolkit ? ' (toolkit)' : '') + '</span><span class="ms-auto"><span class="score-pill">score ' + a.score + '</span> ' + Object.keys(a.bySeverity).map(function (s) { return sevBadge(s) + ' ' + a.bySeverity[s]; }).join(' ') + (a.objectId && state.report.uploadKept !== false ? ' <a class="btn btn-sm btn-outline-primary ms-2" href="#/report/' + state.id + '/objects/' + encodeURIComponent(a.objectId) + '"><i class="fa-solid fa-diagram-project"></i></a>' : '') + (a.designerUrl ? ' <a class="btn btn-sm btn-outline-secondary ms-1" href="' + esc(a.designerUrl) + '" target="_blank" title="Open in Process Designer"><i class="fa-solid fa-arrow-up-right-from-square"></i></a>' : '') + '</span></div>' +
          '<table class="table table-sm findings-table mt-2 mb-0"><tbody>' + a.findings.map(function (f) { return '<tr class="selectable" data-key="' + esc(f.key) + '"><td style="width:120px">' + sevBadge(f.severity) + ' <span class="score-pill">' + f.score + '</span></td><td><b>' + esc(f.ruleId) + '</b> ' + esc(f.title) + (f.itemName ? '<div class="small-muted">' + esc(f.itemName) + (f.line ? ' line ' + f.line : '') + '</div>' : '') + '</td><td>' + esc(f.message) + '<div class="small text-success"><i class="fa-solid fa-wrench me-1"></i>' + esc(f.remediation) + '</div></td></tr>'; }).join('') + '</tbody></table></div>'; }).join('');
      el.querySelectorAll('tr[data-key]').forEach(function (tr) { tr.addEventListener('click', function () { var f = state.report.findings.filter(function (x) { return x.key === tr.getAttribute('data-key'); })[0]; if (f) T.findingDetail(f); }); });
