    if (a) a.addEventListener('click', function () { var reason = prompt('Why is this finding accepted (false positive, planned, risk accepted ...)? The reason is recorded with your name.'); if (reason === null) return; post('api/enterprise/suppressions', { key: x.key, reason: reason, path: x.path }, 'PUT').then(reload).catch(function (e) { alert(e.message || e); }); });
